import{sampleField}from'./terrain-materials.js';
// Continuous material coordinates belong to the world, not to atlas cells.
// Native source indices still own silhouettes, collision and animation.
export function mirrorCoordinate(v,size){const n=((v%(size*2))+size*2)%(size*2);return n<size?n:size*2-1-n;}
export function worldMaterial(level,pixels,value){let wood=0,purple=0,stone=0,olive=0,green=0,ink=0;for(const v of pixels){if(v>=1&&v<=3)wood++;if(v===4)purple++;if(v>=12)stone++;if(v===11)olive++;if(v>=8&&v<=10)green++;if(v!==0&&v!==6)ink++;}if(level==='5'&&wood+olive>0&&green<8)return'autumn-wood';if(level==='6'&&(value>=92&&value<=151||value>=46&&value<=52||value>=66&&value<=70)&&wood>=24&&green<32)return'wood';if(['9','A','F'].includes(level)){if(level==='F'&&value<37)return'glyph-purple';if(level==='F'&&value<256)return null;if(purple>=8&&stone<180)return'purple-stone';if(ink>=32&&stone>=12&&wood<4&&olive<45&&purple<12)return'green-stone';}return null;}
export function cavityIndex(level,index){return level==='8'&&index===6?0:index;}
export function worldPaintSampler({base,source,width,columns,kinds,originX,originY,materials,object,textures=[],semantic=null,palette=[]}){const semanticEntries=semantic?Object.entries(semantic.fields):null,out=new Float32Array(4),underlay=kinds.map((kind,i)=>{if(kind||!materials.wood)return false;let green=0;const tx=i%columns*16,ty=(i/columns|0)*16;for(let y=0;y<16;y++)for(let x=0;x<16;x++){const v=source[(ty+y)*width+tx+x];if(v>=8&&v<=10)green++;}return green>=8&&[i-1,i+1,i-columns,i+columns].filter(n=>kinds[n]==='wood').length>=2;});return(x,y)=>{out.set(base(x,y));const wx=originX*4+x,wy=originY*4+y;if(object&&wx>=object.x*4&&wx<(object.x+object.width/4)*4&&wy>=object.y*4&&wy<(object.y+object.height/4)*4){const p=((wy-object.y*4)*object.width+wx-object.x*4)*4;const edge=Math.min(wx-object.x*4,object.x*4+object.width-wx,wy-object.y*4,object.y*4+object.height-wy),t=Math.max(0,Math.min(1,edge/((object.feather??8)*4))),a=t*t*(3-2*t)*(object.data[p+3]/255);for(let k=0;k<3;k++)out[k]=out[k]*(1-a)+object.data[p+k]*a;out[3]=1;return out;}
 if(semantic){let total=0,r=0,g=0,b=0;for(const[name,field]of semanticEntries){const mat=materials[name];if(!mat)continue;const a=sampleField(field,width,semantic.height,x,y);if(a<=0)continue;const mx=mat.repeat?((wx%mat.width)+mat.width)%mat.width:mirrorCoordinate(wx,mat.width),my=mat.repeat?((wy%mat.height)+mat.height)%mat.height:mirrorCoordinate(wy,mat.height),p=(my*mat.width+mx)*4;let rr=mat.data[p],gg=mat.data[p+1],bb=mat.data[p+2];if(name==='forest-leaves'&&semantic.level==='3'){rr*=.3;bb=bb*.2+gg*.85;gg*=.85;}r+=rr*a;g+=gg*a;b+=bb*a;total+=a;}const index=source[(y>>2)*width+(x>>2)];if(index===6){out[0]=palette[18]||0;out[1]=palette[19]||0;out[2]=palette[20]||0;out[3]=1;}const keep=1-Math.min(1,total);out[0]=out[0]*keep+r;out[1]=out[1]*keep+g;out[2]=out[2]*keep+b;if(total)out[3]=1;return out;}
 const cell=(y>>6)*columns+(x>>6),kind=kinds[cell],glyph=kind==='glyph-purple'?textures[cell]:null,savedR=out[0],savedG=out[1],savedB=out[2];let mat=materials[kind==='glyph-purple'?'purple-stone':kind];if(!mat&&materials.wood&&source[(y>>2)*width+(x>>2)]===6&&underlay[cell])mat=materials.wood;if(!mat)return out;const p=(mirrorCoordinate(wy,mat.height)*mat.width+mirrorCoordinate(wx,mat.width))*4;out[0]=mat.data[p];out[1]=mat.data[p+1];out[2]=mat.data[p+2];out[3]=1;if(glyph){const mask=glyphInk(glyph),a=mask[(y&63)*64+(x&63)]/255;out[0]=out[0]*(1-a)+savedR*a;out[1]=out[1]*(1-a)+savedG*a;out[2]=out[2]*(1-a)+savedB*a;}return out;};}
// Native index6 also fills empty space inside edge fragments. Retain thin
// stone cracks as material detail, but open broad cavities continuously.
export function openMaterialCavities(source,width){const height=source.length/width,eroded=new Uint8Array(source.length),open=new Uint8Array(source.length),disk=[];for(let y=-3;y<=3;y++)for(let x=-3;x<=3;x++)if(x*x+y*y<=9)disk.push([x,y]);for(let y=3;y<height-3;y++)for(let x=3;x<width-3;x++){let empty=true;for(const[dx,dy]of disk){const v=source[(y+dy)*width+x+dx];if(v!==0&&v!==6){empty=false;break;}}if(empty)eroded[y*width+x]=1;}for(let y=3;y<height-3;y++)for(let x=3;x<width-3;x++)if(eroded[y*width+x])for(const[dx,dy]of disk)open[(y+dy)*width+x+dx]=1;const out=source.slice();for(let p=0;p<out.length;p++)if(source[p]===6&&open[p])out[p]=0;return out;}
export function preserveMaterialVoids(paint,source,opened,width){const height=source.length/width,out=new Float32Array(4),at=(x,y)=>{const p=Math.max(0,Math.min(height-1,y))*width+Math.max(0,Math.min(width-1,x));return source[p]===6&&opened[p]===0?1:0;};return(x,y)=>{out.set(paint(x,y));const xx=(x+.5)/4-.5,yy=(y+.5)/4-.5,ix=Math.floor(xx),iy=Math.floor(yy),fx=xx-ix,fy=yy-iy,a=(at(ix,iy)*(1-fx)+at(ix+1,iy)*fx)*(1-fy)+(at(ix,iy+1)*(1-fx)+at(ix+1,iy+1)*fx)*fy;for(let k=0;k<3;k++)out[k]*=1-a;if(a)out[3]=1;return out;};}

const glyphMasks=new WeakMap();
function glyphInk(texture){let mask=glyphMasks.get(texture);if(mask)return mask;const seed=new Uint8Array(4096);mask=new Uint8Array(4096);for(let i=0;i<4096;i++){const p=i*4,hi=Math.max(texture[p],texture[p+1],texture[p+2]),lo=Math.min(texture[p],texture[p+1],texture[p+2]);if(hi>125&&lo>hi*.55)seed[i]=1;}for(let y=0;y<64;y++)for(let x=0;x<64;x++){let a=0;for(let dy=-3;dy<=3;dy++)for(let dx=-3;dx<=3;dx++){const xx=x+dx,yy=y+dy;if(xx>=0&&xx<64&&yy>=0&&yy<64&&seed[yy*64+xx])a=Math.max(a,Math.max(0,Math.min(1,(3.5-Math.hypot(dx,dy))/1.5)));}mask[y*64+x]=a*255;}glyphMasks.set(texture,mask);return mask;}
